    <a class="gbtn" href="extras.html" data-sfx="extras"><img src="assets/btn-extras.png" alt="EXTRAS"></a>
</main>

<main class="page themes-page" id="pageThemes" hidden>
    <header class="themes-topbar">
        <button class="theme-back" id="themeBack" type="button">back</button>
        <h1>themes</h1>
        <nav class="theme-nav" id="themeNav" aria-label="Theme pages">
            <button class="theme-nav-btn selected" type="button" data-theme-tab="mine">my themes</button>
            <button class="theme-nav-btn" type="button" data-theme-tab="discover">discover</button>
            <button class="theme-nav-btn" type="button" data-theme-tab="create">create</button>
            <button class="theme-nav-btn" type="button" data-theme-tab="stats">stats</button>
        </nav>
    </header>

    <section class="theme-view" id="themeViewMine">
        <h2>my themes</h2>
        <h3>official themes</h3>
        <div class="themes-grid" id="themeOfficialGrid"></div>
        <h3>installed themes</h3>
        <div class="themes-grid" id="themeInstalledGrid"></div>
        <p class="theme-empty" id="themeInstalledEmpty" hidden>no custom themes installed yet</p>
    </section>

    <section class="theme-view" id="themeViewDiscover" hidden>
        <h2>discover</h2>
        <div class="theme-discover-tools">
            <input class="theme-input" id="themeSearch" type="search" placeholder="search themes..." autocomplete="off">
            <select class="sel" id="themeSort" aria-label="Sort themes">
                <option value="newest">newest</option>
                <option value="az">A–Z</option>
                <option value="favorites">favorites</option>
            </select>
        </div>
        <p class="theme-catalog-status" id="themeCatalogStatus" role="status">community catalog is temporarily unavailable; showing built-in themes</p>
        <div class="themes-grid" id="themeDiscoverGrid"></div>
        <div id="themeDiscoverMore" class="theme-load-more" aria-hidden="true"></div>
        <p class="theme-empty" id="themeDiscoverEmpty" hidden>no themes match your search</p>
    </section>

    <section class="theme-view" id="themeViewCreate" hidden>
        <h2>create theme</h2>
        <div class="theme-create-layout">
            <form class="theme-create-form" id="themeCreateForm">
                <label>theme name<input class="theme-input" id="themeName" maxlength="36" required placeholder="my theme"></label>
                <label>creator<input class="theme-input" id="themeCreator" maxlength="36" placeholder="local creator"></label>
                <label>description<textarea class="theme-input" id="themeDescription" maxlength="180" rows="3" placeholder="a short description"></textarea></label>
                <label>background image (up to 30 MB)<input class="theme-input theme-file" id="themeBackground" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></label>
                <label>music (up to 50 MB)<input class="theme-input theme-file" id="themeMusic" type="file" accept="audio/mpeg,audio/ogg,audio/wav,audio/mp4,audio/aac"></label>
                <label>home button layout
                    <select class="sel" id="themeButtonLayout">
                        <option value="default">default</option>
                        <option value="center">stacked center</option>
                        <option value="left">stacked left</option>
                        <option value="right">stacked right</option>
                    </select>
                </label>
                <div class="theme-colors">
                    <label>accent<input id="themeAccent" type="color" value="#ffd75e"></label>
                    <label>text<input id="themeText" type="color" value="#fff4e0"></label>
                    <label>background<input id="themeColorBg" type="color" value="#1e1a16"></label>
                </div>
                <div class="theme-form-actions">
                    <button class="theme-action primary" type="submit">save theme</button>
                    <button class="theme-action" id="themeSaveDraft" type="button">save draft</button>
                </div>
                <div class="theme-draft-tools">
                    <select class="sel" id="themeDraftSelect" aria-label="Saved theme drafts"><option value="">select a draft</option></select>
                    <button class="theme-action" id="themeLoadDraft" type="button">load</button>
                    <button class="theme-action" id="themeDeleteDraft" type="button">delete</button>
                </div>
                <p class="theme-form-note" id="themeFormNote" aria-live="polite">themes are saved in this browser</p>
            </form>
            <div class="theme-preview-wrap">
                <h3>preview</h3>
                <div class="theme-preview" id="themePreview">
                    <span class="preview-title">pizza unblocked</span>
                    <span class="preview-buttons"><i>pizza tower</i><i>mods</i><i>extras</i></span>
                </div>
            </div>
        </div>
    </section>

    <section class="theme-view" id="themeViewStats" hidden>
        <h2>theme stats</h2>
        <p class="theme-stats-note">your theme activity on this device</p>
        <div class="theme-stats-grid" id="themeStats"></div>
    </section>
</main>

<main class="page library-page" id="pageLibrary" hidden>
