<script>// ---------- theme music (from js/music.js: bgm, bgmStarted, bgmWanted) ----------

// ---------- icon sfx ----------
const sfx = {};
function playSfx(name) {
    if (!sfx[name]) { sfx[name] = new Audio('assets/sfx/' + name + '.ogg'); sfx[name].preload = 'auto'; }
    const a = sfx[name];
    a.currentTime = 0;
    a.play().catch(() => {});
}
for (const el of document.querySelectorAll('[data-sfx]')) {
    const name = el.dataset.sfx;
    el.addEventListener('mouseenter', () => playSfx(name));
    el.addEventListener('click', () => playSfx(name));
}

// ---------- popups ----------
function openPop(id) { document.getElementById(id).hidden = false; }
function closePop(id) { document.getElementById(id).hidden = true; }
for (const b of document.querySelectorAll('[data-close]'))
    b.addEventListener('click', () => closePop(b.dataset.close));
for (const o of document.querySelectorAll('.overlay'))
    o.addEventListener('mousedown', (e) => { if (e.target === o) o.hidden = true; });
document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') for (const o of document.querySelectorAll('.overlay')) o.hidden = true;
});

document.getElementById('gearBtn').addEventListener('click', () => openPop('popSettings'));
document.getElementById('clBtn').addEventListener('click', () => { renderChangelog(); openPop('popChangelog'); });
const DISCORD_URL = 'https://discord.gg/T2ZHkW9sHU';
// arrow icon = single-file downloads; pizza icon = discord
document.getElementById('dlBtn').addEventListener('click', () => openPop('popSoon'));
// fetch->blob so the download works cross-origin (plain href+download is
// ignored cross-origin and would just navigate into the file)
async function downloadFile(name) {
    try {
        const r = await fetch(name, { cache: 'no-store' });
        if (!r.ok) throw 0;
        const b = await r.blob();
        const a = document.createElement('a');
        a.href = URL.createObjectURL(b);
        a.download = name;
        a.click();
        setTimeout(() => URL.revokeObjectURL(a.href), 5000);
    } catch { /* host unreachable */ }
}
document.getElementById('dlHtml')?.addEventListener('click', () => downloadFile('single-file.html'));
document.getElementById('dlSvg')?.addEventListener('click', () => downloadFile('single-file.svg'));
const pizzaBtn = document.querySelector('.pizza-icon');
pizzaBtn.removeAttribute('onclick');
pizzaBtn.title = 'discord';
pizzaBtn.addEventListener('click', () => window.open(DISCORD_URL, '_blank'));

// Live count of visible browsers connected to the main site.
(() => {
    const badge = document.getElementById('viewerCount');
    if (!badge || !('WebSocket' in window)) return;
    const endpoint = 'wss://pizza-viewer-count.sm64noahm.workers.dev/ws';
    let socket, retryTimer, pingTimer;
    function disconnect() {
        clearTimeout(retryTimer);
        clearInterval(pingTimer);
        if (socket) { socket.onclose = null; socket.close(); socket = null; }
    }
    function connect() {
        disconnect();
        if (document.visibilityState !== 'visible') return;
        socket = new WebSocket(endpoint);
        socket.onmessage = event => {
            try {
                const count = Number(JSON.parse(event.data).viewers);
                if (Number.isInteger(count) && count >= 0) {
                    badge.textContent = `${count} viewing`;
                    badge.title = `${count} people currently viewing this site`;
                }
            } catch { /* ignore malformed updates */ }
        };
        socket.onopen = () => { pingTimer = setInterval(() => socket?.readyState === WebSocket.OPEN && socket.send('ping'), 25000); };
        socket.onclose = () => { clearInterval(pingTimer); if (document.visibilityState === 'visible') retryTimer = setTimeout(connect, 5000); };
        socket.onerror = () => socket?.close();
    }
    document.addEventListener('visibilitychange', () => document.visibilityState === 'visible' ? connect() : disconnect());
    connect();
})();

// ---------- changelog ----------
function renderChangelog() {
    const body = document.getElementById('clBody');
    body.innerHTML = '';
    for (const e of CHANGELOG) {
        const h = document.createElement('div');
        h.className = 'cl-head';
        h.innerHTML = `<span class="cl-title">${e.title}</span> <span class="cl-date">${e.date}</span>`;
        body.appendChild(h);
        for (const g of e.groups) {
            const lbl = document.createElement('div');
            lbl.className = 'cl-label';
            lbl.textContent = g.label;
            body.appendChild(lbl);
            const ul = document.createElement('ul');
            ul.className = 'cl-list';
            for (const it of g.items) {
                const li = document.createElement('li');
                li.textContent = it;
                ul.appendChild(li);
            }
            body.appendChild(ul);
        }
    }
}

// ---------- settings ----------
const audioBtn = document.getElementById('audioBtn');
const volSlider = document.getElementById('volSlider');
function syncAudioUi() {
    const on = localStorage.getItem('pu_audio') !== 'off';
    audioBtn.textContent = 'audio: ' + (on ? 'on' : 'off');
    audioBtn.classList.toggle('sel', on);
    volSlider.value = Math.round(bgm.volume * 100);
}
audioBtn.addEventListener('click', () => {
    const on = localStorage.getItem('pu_audio') !== 'off';
    localStorage.setItem('pu_audio', on ? 'off' : 'on');
    if (on) bgm.pause(); else { bgmStarted = true; bgm.play().catch(() => {}); }
    syncAudioUi();
});
volSlider.addEventListener('input', () => {
    bgm.volume = volSlider.value / 100;
    localStorage.setItem('pu_vol', volSlider.value);
});
syncAudioUi();

// tab cloak
const CLOAKS = {
    google: ['Google', 'https://www.google.com/favicon.ico'],
    canvas: ['Canvas', 'https://www.instructure.com/favicon.ico'],
    clever: ['Clever | Portal', 'https://clever.com/favicon.ico'],
    drive: ['My Drive - Google Drive', 'https://ssl.gstatic.com/docs/doclist/images/drive_2022q3_32dp.png'],
    classroom: ['Classes', 'https://ssl.gstatic.com/classroom/favicon.png'],
};
const cloakSel = document.getElementById('cloakSel');
const VIEW_TITLES = { home: 'Pizza Unblocked', mods: 'Mods — Pizza Unblocked', extras: 'Extras — Pizza Unblocked', library: 'Game Library — Pizza Unblocked', credits: 'Credits — Pizza Unblocked', themes: 'Themes — Pizza Unblocked' };
let curView = 'home';
function applyCloak(key) {
    const c = CLOAKS[key];
    document.title = c ? c[0] : VIEW_TITLES[curView];
    let link = document.querySelector('link[rel="icon"]');
    if (!link) { link = document.createElement('link'); link.rel = 'icon'; document.head.appendChild(link); }
    link.href = c ? c[1] : 'assets/favicon-pizza-face.png';
}
cloakSel.value = localStorage.getItem('pu_cloak') || '';
cloakSel.addEventListener('change', () => {
    localStorage.setItem('pu_cloak', cloakSel.value);
    applyCloak(cloakSel.value);
});
applyCloak(cloakSel.value);

const onlineBtn = document.getElementById('onlineBtn');
onlineBtn.textContent = 'online counter: on';
onlineBtn.classList.add('sel');

const panicBtn = document.getElementById('panicBtn');
panicBtn.addEventListener('click', () => {
    const on = localStorage.getItem('pu_panic') === 'on';
    localStorage.setItem('pu_panic', on ? 'off' : 'on');
    panicBtn.textContent = 'panic button: ' + (on ? 'off' : 'on');
    panicBtn.classList.toggle('sel', !on);
});
panicBtn.textContent = 'panic button: ' + (localStorage.getItem('pu_panic') === 'on' ? 'on' : 'off');
panicBtn.classList.toggle('sel', localStorage.getItem('pu_panic') === 'on');
document.addEventListener('keydown', (e) => {
    if (e.key === '`' && localStorage.getItem('pu_panic') === 'on') location.href = 'https://classroom.google.com';
});

// about:blank cloak — opens the whole site in a popup whose URL bar and
// history entry just say "about:blank"; everything runs inside an iframe.
document.getElementById('blankBtn').addEventListener('click', () => {
    const w = window.open('about:blank', '_blank');
    if (!w) return;
    const file = location.pathname.split('/').pop() || 'index.html';
    const src = new URL(file, appBase.href).href;
    w.document.write(`<!DOCTYPE html><html><head>
<title>Classes</title>
<link rel="icon" href="https://ssl.gstatic.com/classroom/favicon.png">
<style>html,body,iframe{height:100%;width:100%;margin:0;border:0;display:block}</style>
</head><body><iframe src="${src}"></iframe></body></html>`);
    w.document.close();
    location.replace('https://classroom.google.com'); // overwrite this tab's history entry
});

// blob cloak — same wrapper, but the popup's address bar shows an opaque
// blob: URL and the history entry can't be traced back to a real path.
// The popup has to finish loading BEFORE we leave: navigating away kills the
// document that owns the blob, which revokes the URL under the popup.
document.getElementById('blobBtn').addEventListener('click', () => {
    const file = location.pathname.split('/').pop() || 'index.html';
    const src = new URL(file, appBase.href).href;
    const html = `<!DOCTYPE html><html><head>
<title>Classes</title>
<link rel="icon" href="https://ssl.gstatic.com/classroom/favicon.png">
<style>html,body,iframe{height:100%;width:100%;margin:0;border:0;display:block}</style>
</head><body><iframe src="${src}"></iframe></body></html>`;
    const blobUrl = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
    const w = window.open(blobUrl, '_blank');
    if (!w) { URL.revokeObjectURL(blobUrl); return; }
    let left = false;
    const leave = () => {
        if (left) return;
        left = true;
        URL.revokeObjectURL(blobUrl);
        location.replace('https://classroom.google.com'); // overwrite this tab's history entry
    };
    w.onload = leave;
    setTimeout(leave, 4000); // never strand the tab if load doesn't fire
});

// ---------- tools ----------
const padBtn = document.getElementById('padBtn');
function syncPadUi() {
    const on = localStorage.getItem('pu_gamepad') !== 'off';
    const n = ('getGamepads' in navigator ? navigator.getGamepads() : []).filter(p => p && p.connected).length;
    padBtn.textContent = 'controller: ' + (on ? 'on' : 'off') + (n ? ` (${n} connected)` : '');
    padBtn.classList.toggle('sel', on);
}
padBtn.addEventListener('click', () => {
    const on = localStorage.getItem('pu_gamepad') !== 'off';
    localStorage.setItem('pu_gamepad', on ? 'off' : 'on');
    syncPadUi();
});
window.addEventListener('gamepadconnected', syncPadUi);
window.addEventListener('gamepaddisconnected', syncPadUi);
syncPadUi();

// Mobile controls are stored on the site origin, which game pages share.
const touchModeSel = document.getElementById('touchModeSel');
const touchLayoutSel = document.getElementById('touchLayoutSel');
if (touchModeSel) {
    const oldMode = localStorage.getItem('pu_touch');
    touchModeSel.value = localStorage.getItem('pu_touch_mode') || (oldMode === 'on' ? 'on' : oldMode === 'off' ? 'off' : 'auto');
    touchModeSel.addEventListener('change', () => localStorage.setItem('pu_touch_mode', touchModeSel.value));
}
if (touchLayoutSel) {
    touchLayoutSel.value = localStorage.getItem('pu_touch_layout') || 'joystick';
    touchLayoutSel.addEventListener('change', () => localStorage.setItem('pu_touch_layout', touchLayoutSel.value));
}

// ---------- themes ----------
// PU_THEMES comes from js/music.js — bg = background image, song = music track
const bgimgEl2 = document.querySelector('.bgimg');
const themeGrid = document.getElementById('themeGrid');

function applyTheme(t, track = true) {
    const isCustom = Boolean(t.custom);
    bgimgEl2.src = t.bg;
    bgimgEl2.className = 'bgimg ' + (t.cls || '');
    document.getElementById('pageHome').dataset.themeLayout = t.buttonLayout && t.buttonLayout !== 'default' ? t.buttonLayout : '';
    {
        const src = t.song || PU_THEMES.find(theme => theme.name === localStorage.getItem('pu_theme'))?.song || PU_THEMES[0].song;
        if (!bgm.src.endsWith(src)) {
            const wasPlaying = bgmStarted && !bgm.paused;
            bgm.src = src;
            try { bgm.currentTime = 0; } catch {}
            localStorage.setItem('pu_pos', 0);
            if (wasPlaying) bgm.play().catch(() => {});
        }
    }
    if (!isCustom) {
        localStorage.setItem('pu_theme', t.name);
        localStorage.removeItem('pu_theme_custom');
    } else {
        localStorage.setItem('pu_theme_custom', t.id);
        localStorage.removeItem('pu_theme');
    }
    const colors = t.colors || { bg: '#1e1a16', text: '#fff4e0', accent: '#ffd75e', muted: '#b8a89a' };
    document.documentElement.style.setProperty('--bg', colors.bg || '#1e1a16');
    document.documentElement.style.setProperty('--text', colors.text || '#fff4e0');
    document.documentElement.style.setProperty('--yellow', colors.accent || '#ffd75e');
    document.documentElement.style.setProperty('--muted', colors.muted || '#b8a89a');
    if (track) localStorage.setItem('pu_theme_applies', String(Number(localStorage.getItem('pu_theme_applies') || 0) + 1));
    for (const c of themeGrid.children) c.classList.toggle('sel', c.dataset.name === t.name);
}
window.applyPuTheme = applyTheme;
for (const t of PU_THEMES) {
    const card = document.createElement('div');
    card.className = 'theme-card';
    card.dataset.name = t.name;
    card.innerHTML = `<img class="tprev ${t.cls || ''}" src="${t.bg}" alt=""><div class="tname">${t.name}</div>`;
    card.addEventListener('click', () => applyTheme(t));
    themeGrid.appendChild(card);
}
let savedCustomTheme;
try { savedCustomTheme = JSON.parse(localStorage.getItem('pu_custom_themes') || '[]').find(t => t.id === localStorage.getItem('pu_theme_custom')); } catch {}
if (savedCustomTheme) applyTheme({ ...savedCustomTheme, custom: true }, false);
else applyTheme(PU_THEMES.find(t => t.name === localStorage.getItem('pu_theme')) || PU_THEMES[0], false);

// ---------- crash log viewer ----------
function renderCrashLog() {
    const el = document.getElementById('crashLog');
    let log = [];
    try { log = JSON.parse(localStorage.getItem('pu_crashlog') || '[]'); } catch {}
    el.textContent = log.length
        ? log.map(e => `[${e.t}] ${e.page}\n  ${e.msg}${e.extra ? '\n  ' + e.extra : ''}`).join('\n\n')
        : 'no crashes logged';
}
document.getElementById('gearBtn').addEventListener('click', renderCrashLog);
document.getElementById('clearLogBtn').addEventListener('click', () => {
    localStorage.removeItem('pu_crashlog');
    renderCrashLog();
});
document.getElementById('copyLogBtn').addEventListener('click', () => {
    const t = document.getElementById('crashLog').textContent;
    (navigator.clipboard ? navigator.clipboard.writeText(t) : Promise.reject()).catch(() => {});
});

// ---------- view router ----------
// home / mods / extras live in one document so the music never restarts.
// URLs look like index.html/mods — the server (or 404.html on static hosts)
// maps them back to index.html.
const VIEW_PAGES = { home: 'pageHome', mods: 'pageMods', extras: 'pageExtras', library: 'pageLibrary', credits: 'pageCredits', themes: 'pageThemes' };
// pushed paths like index.html/mods would break relative links (games/, assets/)
// — pin document.baseURI to the app directory so they always resolve correctly.
const appBase = document.createElement('base');
// Each deployed mirror serves its own shell, assets, and games.
// Single-file builds can still provide their own asset host through PU_HOST.
appBase.href = window.PU_HOST ? window.PU_HOST + '/'
    : location.protocol === 'file:'
        ? location.pathname.replace(/[^/]*$/, '')
        : location.origin + '/';
document.head.prepend(appBase);
function viewFromUrl() {
    const m = location.pathname.match(/\/(mods|extras|library|credits|themes)\/?$/)
        || location.hash.match(/^#\/?(mods|extras|library|credits|themes)$/);
    return m ? m[1] : 'home';
}
function pageUrl(name) {
    const path = location.pathname.replace(/\/(mods|extras|library|credits|themes)\/?$/, '');
    const m = path.match(/[^/]+\.html?$/i);
    return (m ? path.slice(0, m.index) : path.replace(/\/$/, '') + '/')
        + (m ? m[0] : 'index.html') + (name === 'home' ? '' : '/' + name);
}
function showPage(name, push = true) {
    curView = name in VIEW_PAGES ? name : 'home';
    const logo = document.querySelector('a.logo');
    if (logo) {
        logo.setAttribute('href', curView === 'credits' ? 'index.html' : 'credits.html');
        logo.setAttribute('aria-label', curView === 'credits' ? 'Pizza Unblocked — back to menu' : 'Pizza Unblocked — credits');
    }
    for (const v in VIEW_PAGES) document.getElementById(VIEW_PAGES[v]).hidden = v !== curView;
    document.body.dataset.view = curView;
    document.title = (CLOAKS[cloakSel.value] || [VIEW_TITLES[curView]])[0];
    try {
        if (push) history.pushState(null, '', pageUrl(curView));
        else history.replaceState(null, '', pageUrl(curView));
    } catch {
        if (push) location.hash = '/' + curView;
    }
    if (curView === 'home') window.renderHomeShelves?.();
    if (curView === 'library') window.renderLibraryPage?.();
}
// ---------- game overlay ----------
// game links open in an in-page iframe so the real host URL never hits the
// address bar or history — important for the shared single file. The iframe
// carries the host's origin, so its own service worker still stitches chunks
// and COI headers still apply inside it.
let gameOverlay = null;
function openGame(a) {
    // Keep game files on the same host as this copy of the site. Each mirror
    // must carry its own /games tree so a blocked proxy cannot break play.
    const href = a.getAttribute('href').replace(/^(?:mods|extras)\//, 'games/');
    const target = new URL(href, appBase.href);
    const url = target.href;
    const name = (a.querySelector('.cname') || {}).textContent || a.getAttribute('title') || 'game';
    recordGameLaunch(a);
    if (gameOverlay) gameOverlay.remove();
    gameOverlay = document.createElement('div');
    gameOverlay.id = 'gameOverlay';
    gameOverlay.innerHTML =
        '<button class="game-home" type="button" aria-label="Home — main menu">home</button>' +
        '<iframe allowfullscreen allow="autoplay; fullscreen; gamepad; cross-origin-isolated"></iframe>';
    gameOverlay.querySelector('iframe').title = name;
    gameOverlay.querySelector('iframe').src = url;
    gameOverlay.querySelector('.game-home').addEventListener('click', () => {
        closeGame();
        showPage('home', false);
    });
    document.body.appendChild(gameOverlay);
    // Keep Enter inside the game instead of reactivating its menu card.
    const gameFrame = gameOverlay.querySelector('iframe');
    gameFrame.focus();
    gameFrame.addEventListener('load', () => {
        if (gameOverlay && gameOverlay.contains(gameFrame) && document.activeElement === gameFrame) {
            gameFrame.contentWindow.focus();
        }
    });
    document.body.dataset.gameOpen = '1';
    // pause unconditionally — gating on bgmStarted misses the race where this
    // very click is the first gesture and kickBgm's play() is still in-flight
    gameOverlay._bgmWas = bgmWanted;
    bgm.pause();
    try { history.pushState({ game: 1 }, '', '#game'); } catch { location.hash = 'game'; }
}
function closeGame() {
    if (!gameOverlay) return;
    const wasMusic = gameOverlay._bgmWas;
    gameOverlay.remove();
    gameOverlay = null;
    delete document.body.dataset.gameOpen;
    if (wasMusic && bgmWanted) bgm.play().then(() => { bgmStarted = true; }).catch(() => {});
}
document.addEventListener('click', (e) => {
    const a = e.target.closest('a[href]');
    if (!a) return;
    const href = a.getAttribute('href');
    const view = href === 'mods.html' ? 'mods' : href === 'extras.html' ? 'extras' : href === 'index.html/library' ? 'library' : href === 'credits.html' ? 'credits' : href === 'index.html' ? 'home' : null;
    if (view) { e.preventDefault(); showPage(view); return; }
    if (/^(?:games|mods|extras)\//.test(href) || (a.classList.contains('card') && /^https?:/.test(href))) { e.preventDefault(); openGame(a); }
});
// file:// can't pushState, so openGame falls back to location.hash='game' —
// that hash nav fires popstate too; only close when we've actually left #game.
window.addEventListener('popstate', () => {
    if (gameOverlay && location.hash !== '#game') closeGame();
    showPage(viewFromUrl(), false);
});
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && gameOverlay) history.back(); });
showPage(viewFromUrl(), false);
</script>
<script>// Local theme browser, inspired by the Toby Web theme screens.
(() => {
    const CUSTOM_KEY = 'pu_custom_themes';
    const INSTALLED_KEY = 'pu_installed_themes';
    const FAVORITES_KEY = 'pu_theme_favorites';
    const countKey = 'pu_theme_applies';
    let customCache;
    const tabs = document.getElementById('themeNav');
    const sections = {
        mine: document.getElementById('themeViewMine'),
        discover: document.getElementById('themeViewDiscover'),
        create: document.getElementById('themeViewCreate'),
        stats: document.getElementById('themeViewStats'),
    };
    const read = (key, fallback) => {
        try {
            const value = JSON.parse(localStorage.getItem(key) || 'null');
            return value ?? fallback;
        } catch { return fallback; }
    };
    customCache = read(CUSTOM_KEY, []);
    const customThemes = () => customCache.filter(theme => theme && theme.id && theme.name);
    const installedThemes = () => read(INSTALLED_KEY, []);
    const activeKey = () => localStorage.getItem('pu_theme_custom') || `official:${localStorage.getItem('pu_theme') || PU_THEMES[0].name}`;
    let selectedTab = 'mine';
    let previewObjectUrl = '';
    let discoverLimit = 12;

    function openThemeDb() {
        return new Promise((resolve, reject) => {
            const request = indexedDB.open('pizza-unblocked-themes', 1);
            request.onupgradeneeded = () => request.result.createObjectStore('state');
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        });
    }
    async function readDb(key) {
        const db = await openThemeDb();
        return new Promise((resolve, reject) => {
            const request = db.transaction('state').objectStore('state').get(key);
            request.onsuccess = () => resolve(request.result);
            request.onerror = () => reject(request.error);
        });
    }
    async function writeDb(key, value) {
        const db = await openThemeDb();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction('state', 'readwrite');
            transaction.objectStore('state').put(value, key);
            transaction.oncomplete = () => resolve();
            transaction.onerror = () => reject(transaction.error);
            transaction.onabort = () => reject(transaction.error);
        });
    }
    async function removeDb(key) {
        const db = await openThemeDb();
        return new Promise((resolve, reject) => {
            const transaction = db.transaction('state', 'readwrite');
            transaction.objectStore('state').delete(key);
            transaction.oncomplete = () => resolve();
            transaction.onerror = () => reject(transaction.error);
        });
    }
    async function loadPersistedThemes() {
        try {
            const stored = await readDb('custom');
            if (Array.isArray(stored)) customCache = stored;
            else {
                const legacy = read(CUSTOM_KEY, []);
                if (Array.isArray(legacy) && legacy.length) {
                    customCache = legacy;
                    await writeDb('custom', customCache);
                }
            }
            localStorage.setItem(CUSTOM_KEY, '[]');
            const active = customThemes().find(theme => theme.id === localStorage.getItem('pu_theme_custom'));
            if (active) window.applyPuTheme({ ...active, custom: true }, false);
            renderAll();
            refreshDraftSelect();
        } catch {
            document.getElementById('themeFormNote').textContent = 'browser storage is unavailable; themes may not save';
        }
    }

    function crc32(bytes) {
        let crc = -1;
        for (const byte of bytes) {
            crc ^= byte;
            for (let i = 0; i < 8; i++) crc = (crc >>> 1) ^ (0xedb88320 & -(crc & 1));
        }
        return (crc ^ -1) >>> 0;
    }
    function zipStore(files) {
        const encoder = new TextEncoder();
        const localParts = [], centralParts = [];
        let offset = 0;
        for (const file of files) {
            const name = encoder.encode(file.name), data = file.data instanceof Uint8Array ? file.data : encoder.encode(file.data);
            const crc = crc32(data);
            const local = new Uint8Array(30 + name.length + data.length), lv = new DataView(local.buffer);
            lv.setUint32(0, 0x04034b50, true); lv.setUint16(4, 20, true); lv.setUint32(14, crc, true);
            lv.setUint32(18, data.length, true); lv.setUint32(22, data.length, true); lv.setUint16(26, name.length, true);
            local.set(name, 30); local.set(data, 30 + name.length); localParts.push(local);
            const central = new Uint8Array(46 + name.length), cv = new DataView(central.buffer);
            cv.setUint32(0, 0x02014b50, true); cv.setUint16(4, 20, true); cv.setUint16(6, 20, true);
            cv.setUint32(16, crc, true); cv.setUint32(20, data.length, true); cv.setUint32(24, data.length, true);
            cv.setUint16(28, name.length, true); cv.setUint32(42, offset, true); central.set(name, 46);
            centralParts.push(central); offset += local.length;
        }
        const centralSize = centralParts.reduce((sum, part) => sum + part.length, 0);
        const end = new Uint8Array(22), view = new DataView(end.buffer);
        view.setUint32(0, 0x06054b50, true); view.setUint16(8, files.length, true); view.setUint16(10, files.length, true);
        view.setUint32(12, centralSize, true); view.setUint32(16, offset, true);
        return new Blob([...localParts, ...centralParts, end], { type: 'application/zip' });
    }
    function dataUrlBytes(url) {
        if (!url || !url.startsWith('data:')) return null;
        const [meta, encoded] = url.split(',', 2);
        if (!meta.includes(';base64')) return new TextEncoder().encode(decodeURIComponent(encoded));
        const raw = atob(encoded), bytes = new Uint8Array(raw.length);
        for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
        return bytes;
    }
    async function exportTheme(theme) {
        const bgName = `background.${theme.bg?.match(/^data:image\/([^;]+)/)?.[1] || 'bin'}`;
        const songName = `music.${theme.song?.match(/^data:audio\/([^;]+)/)?.[1] || 'bin'}`;
        const metadata = { ...theme, bg: theme.bg?.startsWith('data:') ? bgName : theme.bg, song: theme.song?.startsWith('data:') ? songName : theme.song };
        const files = [{ name: 'theme.json', data: JSON.stringify(metadata, null, 2) }];
        const background = dataUrlBytes(theme.bg);
        if (background) files.push({ name: bgName, data: background });
        const music = dataUrlBytes(theme.song);
        if (music) files.push({ name: songName, data: music });
        const blob = zipStore(files), url = URL.createObjectURL(blob), anchor = document.createElement('a');
        anchor.href = url; anchor.download = `${theme.name.toLowerCase().replace(/[^a-z0-9]+/g, '-') || 'theme'}.zip`;
        anchor.click(); setTimeout(() => URL.revokeObjectURL(url), 30000);
    }

    function selectTab(name) {
        selectedTab = name in sections ? name : 'mine';
        for (const [key, section] of Object.entries(sections)) section.hidden = key !== selectedTab;
        for (const button of tabs.querySelectorAll('[data-theme-tab]')) {
            const selected = button.dataset.themeTab === selectedTab;
            button.classList.toggle('selected', selected);
            button.setAttribute('aria-current', selected ? 'page' : 'false');
        }
        if (selectedTab === 'stats') renderStats();
    }

    function addTile(container, theme, { custom = false, discover = false } = {}) {
        const key = custom ? theme.id : `official:${theme.name}`;
        const tile = document.createElement('article');
        tile.className = 'theme-tile';
        if (activeKey() === key) tile.classList.add('active');

        const image = document.createElement('button');
        image.type = 'button';
        image.className = 'theme-tile-image';
        image.setAttribute('aria-label', `Apply ${theme.name}`);
        image.style.background = `center / cover url("${theme.bg}") #111`;
        image.addEventListener('click', () => {
            window.applyPuTheme({ ...theme, custom });
            renderAll();
        });
        tile.appendChild(image);

        const title = document.createElement('strong');
        title.className = 'theme-tile-title';
        title.textContent = theme.name;
        tile.appendChild(title);
        const creator = document.createElement('span');
        creator.className = 'theme-tile-creator';
        creator.textContent = theme.creator || (custom ? 'local creator' : 'Pizza Unblocked');
        tile.appendChild(creator);

        const favoriteIds = new Set(read(FAVORITES_KEY, []));
        const favorite = document.createElement('button');
        favorite.type = 'button'; favorite.className = 'theme-favorite';
        favorite.textContent = favoriteIds.has(key) ? '★' : '☆';
        favorite.title = favoriteIds.has(key) ? 'remove favorite theme' : 'favorite theme';
        favorite.setAttribute('aria-pressed', String(favoriteIds.has(key)));
        favorite.addEventListener('click', () => {
            const next = new Set(read(FAVORITES_KEY, []));
            if (next.has(key)) next.delete(key); else next.add(key);
            localStorage.setItem(FAVORITES_KEY, JSON.stringify([...next]));
            favorite.textContent = next.has(key) ? '★' : '☆';
            favorite.setAttribute('aria-pressed', String(next.has(key)));
        });
        tile.appendChild(favorite);

        const actions = document.createElement('div');
        actions.className = 'theme-tile-actions';
        const action = document.createElement('button');
        action.type = 'button';
        action.className = 'theme-action';
        if (discover) {
            action.textContent = installedThemes().includes(key) ? 'installed' : 'install';
            action.disabled = installedThemes().includes(key);
            action.addEventListener('click', () => {
                const installed = new Set(installedThemes());
                installed.add(key);
                localStorage.setItem(INSTALLED_KEY, JSON.stringify([...installed]));
                window.applyPuTheme({ ...theme, custom });
                renderAll();
            });
        } else {
            action.textContent = 'apply';
            action.addEventListener('click', () => {
                window.applyPuTheme({ ...theme, custom });
                renderAll();
            });
        }
        actions.appendChild(action);

        if (custom && !discover) {
            const exportButton = document.createElement('button');
            exportButton.type = 'button'; exportButton.className = 'theme-action'; exportButton.textContent = 'export zip';
            exportButton.addEventListener('click', () => exportTheme(theme));
            actions.appendChild(exportButton);
            const remove = document.createElement('button');
            remove.type = 'button';
            remove.className = 'theme-action';
            remove.textContent = 'delete';
            remove.addEventListener('click', () => {
                const remaining = customThemes().filter(item => item.id !== theme.id);
                customCache = remaining;
                writeDb('custom', customCache).catch(() => {});
                localStorage.setItem(INSTALLED_KEY, JSON.stringify(installedThemes().filter(item => item !== theme.id)));
                if (localStorage.getItem('pu_theme_custom') === theme.id) window.applyPuTheme(PU_THEMES[0]);
                renderAll();
            });
            actions.appendChild(remove);
        }
        tile.appendChild(actions);
        container.appendChild(tile);
    }

    function renderMine() {
        const officialGrid = document.getElementById('themeOfficialGrid');
        const installedGrid = document.getElementById('themeInstalledGrid');
        officialGrid.replaceChildren();
        installedGrid.replaceChildren();
        for (const theme of PU_THEMES) addTile(officialGrid, theme);
        for (const theme of customThemes()) addTile(installedGrid, theme, { custom: true });
        document.getElementById('themeInstalledEmpty').hidden = customThemes().length > 0;
    }

    function renderDiscover() {
        const grid = document.getElementById('themeDiscoverGrid');
        const empty = document.getElementById('themeDiscoverEmpty');
        const query = document.getElementById('themeSearch').value.trim().toLowerCase();
        const sort = document.getElementById('themeSort').value;
        let themes = [...PU_THEMES].filter(theme => theme.name.toLowerCase().includes(query));
        if (sort === 'az') themes.sort((a, b) => a.name.localeCompare(b.name));
        if (sort === 'favorites') themes = themes.filter(theme => read(FAVORITES_KEY, []).includes(`official:${theme.name}`));
        grid.replaceChildren();
        for (const theme of themes.slice(0, discoverLimit)) addTile(grid, theme, { discover: true });
        document.getElementById('themeDiscoverMore').hidden = themes.length <= discoverLimit;
        empty.hidden = themes.length > 0;
    }

    function draftValue() {
        return {
            name: nameInput.value.trim(), creator: document.getElementById('themeCreator').value.trim(),
            description: document.getElementById('themeDescription').value.trim(),
            accent: accentInput.value, text: textInput.value, bgColor: bgColorInput.value,
            buttonLayout: document.getElementById('themeButtonLayout').value,
            background: fileInput.files?.[0] || null, music: musicInput.files?.[0] || null,
        };
    }
    async function fileToDataUrl(file) {
        if (!file) return '';
        return new Promise((resolve, reject) => {
            const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject;
            reader.readAsDataURL(file);
        });
    }
    async function readDrafts() { return (await readDb('drafts')) || []; }
    async function refreshDraftSelect() {
        const select = document.getElementById('themeDraftSelect');
        if (!select) return;
        const previous = select.value;
        let drafts = [];
        try { drafts = await readDrafts(); } catch {}
        select.replaceChildren(new Option('select a draft', ''));
        drafts.forEach(draft => select.add(new Option(draft.name || 'untitled draft', draft.id)));
        if (drafts.some(draft => draft.id === previous)) select.value = previous;
    }
    async function saveDraft() {
        const value = draftValue();
        const bg = value.background, song = value.music;
        if (bg && bg.size > 30 * 1024 * 1024) throw new Error('background images must be 30 MB or smaller');
        if (song && song.size > 50 * 1024 * 1024) throw new Error('music files must be 50 MB or smaller');
        const drafts = await readDrafts();
        const draft = {
            id: `draft-${Date.now()}`, name: value.name || 'untitled draft', creator: value.creator,
            description: value.description, accent: value.accent, text: value.text, bgColor: value.bgColor,
            bg: bg ? await fileToDataUrl(bg) : '', song: song ? await fileToDataUrl(song) : '',
        };
        drafts.unshift(draft);
        await writeDb('drafts', drafts.slice(0, 20));
        await refreshDraftSelect();
        document.getElementById('themeFormNote').textContent = 'draft saved in this browser';
    }
    async function loadDraft() {
        const id = document.getElementById('themeDraftSelect').value;
        const draft = (await readDrafts()).find(item => item.id === id);
        if (!draft) return;
        nameInput.value = draft.name || ''; document.getElementById('themeCreator').value = draft.creator || '';
        document.getElementById('themeDescription').value = draft.description || '';
        accentInput.value = draft.accent || '#ffd75e'; textInput.value = draft.text || '#fff4e0'; bgColorInput.value = draft.bgColor || '#1e1a16';
        document.getElementById('themeButtonLayout').value = draft.buttonLayout || 'default';
        fileInput.value = ''; musicInput.value = '';
        const restoreFile = (input, data, name, fallbackType) => {
            if (!data) return;
            const bytes = dataUrlBytes(data);
            const type = data.slice(5, data.indexOf(';')) || fallbackType;
            const transfer = new DataTransfer();
            transfer.items.add(new File([bytes], name, { type })); input.files = transfer.files;
        };
        try { restoreFile(fileInput, draft.bg, 'theme-background', 'image/png'); } catch {}
        try { restoreFile(musicInput, draft.song, 'theme-music', 'audio/mpeg'); } catch {}
        if (draft.bg) preview.style.backgroundImage = `url("${draft.bg}")`;
        updatePreview(); document.getElementById('themeFormNote').textContent = 'draft loaded; reselect media files if you want to edit them';
    }

    function renderStats() {
        const grid = document.getElementById('themeStats');
        const currentCustom = customThemes().find(theme => theme.id === localStorage.getItem('pu_theme_custom'));
        const current = currentCustom?.name || localStorage.getItem('pu_theme') || PU_THEMES[0].name;
        const rows = [
            ['current theme', current],
            ['installed themes', new Set([...installedThemes(), ...customThemes().map(theme => theme.id)]).size],
            ['themes you created', customThemes().length],
            ['theme changes on this device', Number(localStorage.getItem(countKey) || 0)],
        ];
        grid.replaceChildren();
        for (const [label, value] of rows) {
            const row = document.createElement('div');
            row.className = 'theme-stat';
            const title = document.createElement('span');
            title.textContent = label;
            const count = document.createElement('strong');
            count.textContent = String(value);
            row.append(title, count);
            grid.appendChild(row);
        }
    }

    function renderAll() {
        renderMine();
        renderDiscover();
        if (selectedTab === 'stats') renderStats();
    }

    document.getElementById('themeBtn').addEventListener('click', () => showPage('themes'));
    document.getElementById('themeBack').addEventListener('click', () => showPage('home'));
    tabs.addEventListener('click', event => {
        const button = event.target.closest('[data-theme-tab]');
        if (button) selectTab(button.dataset.themeTab);
    });
    document.getElementById('themeSearch').addEventListener('input', () => { discoverLimit = 12; renderDiscover(); });
    document.getElementById('themeSort').addEventListener('change', () => { discoverLimit = 12; renderDiscover(); });

    const form = document.getElementById('themeCreateForm');
    const preview = document.getElementById('themePreview');
    const previewTitle = preview.querySelector('.preview-title');
    const nameInput = document.getElementById('themeName');
    const fileInput = document.getElementById('themeBackground');
    const musicInput = document.getElementById('themeMusic');
    const accentInput = document.getElementById('themeAccent');
    const textInput = document.getElementById('themeText');
    const bgColorInput = document.getElementById('themeColorBg');
    const buttonLayoutInput = document.getElementById('themeButtonLayout');
    function updatePreview() {
        previewTitle.textContent = nameInput.value.trim() || 'my theme';
        preview.style.color = textInput.value;
        preview.style.backgroundColor = bgColorInput.value;
        preview.style.borderColor = accentInput.value;
        preview.dataset.layout = buttonLayoutInput.value;
        for (const button of preview.querySelectorAll('.preview-buttons i')) button.style.borderColor = accentInput.value;
    }
    for (const input of [nameInput, accentInput, textInput, bgColorInput, buttonLayoutInput]) input.addEventListener('input', updatePreview);
    buttonLayoutInput.addEventListener('change', updatePreview);
    fileInput.addEventListener('change', () => {
        if (previewObjectUrl) URL.revokeObjectURL(previewObjectUrl);
        const file = fileInput.files?.[0];
        if (!file) return;
        previewObjectUrl = URL.createObjectURL(file);
        preview.style.backgroundImage = `url("${previewObjectUrl}")`;
    });
    const observer = new IntersectionObserver(entries => {
        if (entries.some(entry => entry.isIntersecting)) {
            const total = PU_THEMES.filter(theme => {
                const q = document.getElementById('themeSearch').value.trim().toLowerCase();
                return theme.name.toLowerCase().includes(q);
            }).length;
            if (discoverLimit < total) { discoverLimit += 12; renderDiscover(); }
        }
    });
    observer.observe(document.getElementById('themeDiscoverMore'));
    document.getElementById('themeSaveDraft').addEventListener('click', async () => {
        const note = document.getElementById('themeFormNote');
        try { await saveDraft(); }
        catch (error) { note.textContent = error.message || 'could not save draft in browser storage'; }
    });
    document.getElementById('themeLoadDraft').addEventListener('click', () => loadDraft().catch(() => {}));
    document.getElementById('themeDeleteDraft').addEventListener('click', async () => {
        const select = document.getElementById('themeDraftSelect');
        if (!select.value) return;
        const drafts = (await readDrafts()).filter(draft => draft.id !== select.value);
        await writeDb('drafts', drafts); await refreshDraftSelect();
        document.getElementById('themeFormNote').textContent = 'draft deleted';
    });
    form.addEventListener('submit', async event => {
        event.preventDefault();
        const note = document.getElementById('themeFormNote');
        const file = fileInput.files?.[0];
        const musicFile = musicInput.files?.[0];
        if (file && file.size > 30 * 1024 * 1024) {
            note.textContent = 'background images must be 30 MB or smaller';
            return;
        }
        if (musicFile && musicFile.size > 50 * 1024 * 1024) {
            note.textContent = 'music files must be 50 MB or smaller';
            return;
        }
        let bg = document.querySelector('.bgimg').src;
        if (file) {
            try { bg = await fileToDataUrl(file); }
            catch { note.textContent = 'could not read that image'; return; }
        }
        let song = '';
        if (musicFile) {
            try { song = await fileToDataUrl(musicFile); }
            catch { note.textContent = 'could not read that music file'; return; }
        }
        const theme = {
            id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
            custom: true,
            name: nameInput.value.trim(),
            creator: document.getElementById('themeCreator').value.trim() || 'local creator',
            description: document.getElementById('themeDescription').value.trim(),
            bg,
            song,
            buttonLayout: buttonLayoutInput.value,
            colors: { bg: bgColorInput.value, accent: accentInput.value, text: textInput.value, muted: '#b8a89a' },
        };
        try {
            const saved = [...customThemes(), theme];
            await writeDb('custom', saved);
            customCache = saved;
            localStorage.setItem(CUSTOM_KEY, '[]');
            localStorage.setItem(INSTALLED_KEY, JSON.stringify([...new Set([...installedThemes(), theme.id])]));
            window.applyPuTheme(theme);
            note.textContent = 'theme saved and installed in this browser';
            form.reset();
            if (previewObjectUrl) URL.revokeObjectURL(previewObjectUrl);
            previewObjectUrl = '';
            preview.style.backgroundImage = '';
            updatePreview();
            renderAll();
            selectTab('mine');
        } catch {
            note.textContent = 'could not save in browser storage; try a smaller file';
        }
    });

    loadPersistedThemes();

    selectTab('mine');
    renderAll();
})();
</script>
<script>/* Pizza Unblocked — persistent saves for butterscotch ports.
   The runner's --save-folder is /saves in the in-memory wasm FS, so this
   mirrors it to browser OPFS at /pu-saves/<game>/ and back. Also applies
   pending 101%-save injections and exports backups as .zip downloads. */
const PU_SAVES = (() => {
    const ROOT = 'pu-saves';
    const SAVE_FS = '/saves';

    // cross-origin shells post the 101% payload via postMessage — land it in
    // sessionStorage where injectIfPending picks it up on boot.
    window.addEventListener('message', (e) => {
        const d = e.data;
        if (d && d.pu_saveinject && typeof d.pu_saveinject.files === 'object') {
            try {
                sessionStorage.setItem(
                    'pu_saveinject_' + d.pu_saveinject.dir,
                    JSON.stringify(d.pu_saveinject.files),
                );
            } catch (_) {}
        }
    });

    function dirKeyFromPath() {
        const parts = location.pathname.split('/').filter(Boolean);
        return parts[parts.length - 1] || 'unknown';
    }

    async function dirHandle(dirKey, create = true) {
        const root = await navigator.storage.getDirectory();
        const a = await root.getDirectoryHandle(ROOT, { create });
        return a.getDirectoryHandle(dirKey, { create });
    }

    // recurse one level — PT writes flat inis, mods may nest a subdir
    async function* walkOpfs(dir, prefix = '') {
        for await (const [name, h] of dir.entries()) {
            if (h.kind === 'file') yield { name: prefix + name, handle: h };
            else if (h.kind === 'directory') yield* walkOpfs(h, prefix + name + '/');
        }
    }

    function fsMkdirs(Module, p) {
        let cur = '';
        for (const part of p.split('/')) {
            if (!part) continue;
            cur += '/' + part;
            try { Module.FS.mkdir(cur); } catch {}
        }
    }

    function* walkMemfs(Module, p, prefix = '') {
        for (const name of Module.FS.readdir(p)) {
            if (name === '.' || name === '..') continue;
            const full = p + '/' + name;
            const st = Module.FS.stat(full);
            if (Module.FS.isDir(st.mode)) yield* walkMemfs(Module, full, prefix + name + '/');
            else yield { name: prefix + name, path: full };
        }
    }

    async function opfsMkdirs(dir, rel) {
        const parts = rel.split('/');
        parts.pop();
        for (const part of parts) dir = await dir.getDirectoryHandle(part, { create: true });
        return dir;
    }

    async function restore(Module, dirKey) {
        try {
            const dir = await dirHandle(dirKey, false).catch(() => null);
            if (!dir) return;
            fsMkdirs(Module, SAVE_FS);
            for await (const { name, handle } of walkOpfs(dir)) {
                const f = await handle.getFile();
                fsMkdirs(Module, SAVE_FS + '/' + name.split('/').slice(0, -1).join('/'));
                Module.FS.writeFile(SAVE_FS + '/' + name, new Uint8Array(await f.arrayBuffer()));
            }
            console.log('[saves] restored from opfs');
        } catch (e) { console.warn('[saves] restore failed', e); }
    }

    async function injectIfPending(Module, dirKey) {
        try {
            const raw = sessionStorage.getItem('pu_saveinject_' + dirKey);
            if (!raw) return;
            const files = JSON.parse(raw);
            const dir = await dirHandle(dirKey).catch(() => null);
            for (const [name, text] of Object.entries(files)) {
                Module.FS.writeFile(SAVE_FS + '/' + name, text);
                if (dir) {
                    const fh = await dir.getFileHandle(name, { create: true });
                    const w = await fh.createWritable();
                    await w.write(text);
                    await w.close();
                }
            }
            sessionStorage.removeItem('pu_saveinject_' + dirKey);
            console.log('[saves] injected 101% save');
        } catch (e) { console.warn('[saves] inject failed', e); }
    }

    async function flushOut(Module, dirKey) {
        try {
            const dir = await dirHandle(dirKey);
            for (const { name, path } of walkMemfs(Module, SAVE_FS)) {
                const data = Module.FS.readFile(path);
                const sub = await opfsMkdirs(dir, name);
                const fh = await sub.getFileHandle(name.split('/').pop(), { create: true });
                const w = await fh.createWritable();
                await w.write(data);
                await w.close();
            }
        } catch (e) { /* /saves may not exist yet or opfs unavailable */ }
    }

    function arm(Module, dirKey) {
        setInterval(() => flushOut(Module, dirKey), 5000);
        addEventListener('pagehide', () => { flushOut(Module, dirKey); });
    }

    // --- store-only zip for backups ---
    const CRC_TABLE = (() => {
        const t = new Uint32Array(256);
        for (let n = 0; n < 256; n++) {
            let c = n;
            for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
            t[n] = c;
        }
        return t;
    })();
    function crc32(d) {
        let c = 0xFFFFFFFF;
        for (const b of d) c = CRC_TABLE[(c ^ b) & 0xFF] ^ (c >>> 8);
        return (c ^ 0xFFFFFFFF) >>> 0;
    }
    function zipStore(files) {
        const enc = new TextEncoder();
        const chunks = [], central = [];
        let off = 0;
        for (const [name, data] of Object.entries(files)) {
            const nb = enc.encode(name), crc = crc32(data);
            const h = new DataView(new ArrayBuffer(30));
            h.setUint32(0, 0x04034b50, true); h.setUint16(4, 20, true);
            h.setUint32(14, crc, true); h.setUint32(18, data.length, true);
            h.setUint32(22, data.length, true); h.setUint16(26, nb.length, true);
            chunks.push(h.buffer, nb, data);
            const c = new DataView(new ArrayBuffer(46));
            c.setUint32(0, 0x02014b50, true); c.setUint16(6, 20, true);
            c.setUint32(16, crc, true); c.setUint32(20, data.length, true);
            c.setUint32(24, data.length, true); c.setUint16(28, nb.length, true);
            c.setUint32(42, off, true);
            central.push(c.buffer, nb);
            off += 30 + nb.length + data.length;
        }
        const cdSize = central.reduce((s, b) => s + b.byteLength, 0);
        const e = new DataView(new ArrayBuffer(22));
        e.setUint32(0, 0x06054b50, true);
        const n = Object.keys(files).length;
        e.setUint16(8, n, true); e.setUint16(10, n, true);
        e.setUint32(12, cdSize, true); e.setUint32(16, off, true);
        return new Blob([...chunks, ...central, e.buffer], { type: 'application/zip' });
    }

    async function readOpfsFiles(dirKey) {
        const dir = await dirHandle(dirKey, false).catch(() => null);
        const files = {};
        if (dir) for await (const { name, handle } of walkOpfs(dir)) {
            const f = await handle.getFile();
            files[name] = new Uint8Array(await f.arrayBuffer());
        }
        return files;
    }

    async function downloadBackup(dirKey) {
        const files = await readOpfsFiles(dirKey);
        if (!Object.keys(files).length) return false;
        const a = document.createElement('a');
        a.href = URL.createObjectURL(zipStore(files));
        a.download = dirKey + '-saves-backup.zip';
        a.click();
        setTimeout(() => URL.revokeObjectURL(a.href), 10000);
        return true;
    }

    /* GXMFS (emscripten runner) saves live in localStorage as
       pu_gs:<dir>:<mount>:<file> entries. */
    function readGameStorageFiles(dirKey) {
        const files = {};
        const pfx = 'pu_gs:' + dirKey + ':';
        const enc = new TextEncoder();
        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (!k || !k.startsWith(pfx)) continue;
            let v;
            try { v = JSON.parse(localStorage.getItem(k)); } catch (e) { continue; }
            const name = k.slice(pfx.length).replace(/^_savedata[:/]?/, '').replace(/^\/+/, '');
            if (!name) continue;
            if (typeof v === 'string') files[name] = enc.encode(v);
            else if (v instanceof ArrayBuffer) files[name] = new Uint8Array(v);
            else if (v != null) files[name] = enc.encode(typeof v === 'object' ? JSON.stringify(v) : String(v));
        }
        return files;
    }

    /* Godot / IDBFS saves land in IndexedDB — dump every store entry that
       looks like a file blob, keyed by its stored path. */
    async function readIdbFiles() {
        const files = {};
        let dbs;
        try { dbs = await indexedDB.databases(); } catch (e) { return files; }
        for (const info of dbs || []) {
            if (!info.name) continue;
            try {
                const db = await new Promise((res, rej) => {
                    const r = indexedDB.open(info.name);
                    r.onsuccess = () => res(r.result);
                    r.onerror = () => rej(r.error);
                });
                for (const sn of db.objectStoreNames) {
                    try {
                        const rows = await new Promise((res, rej) => {
                            const tx = db.transaction(sn, 'readonly');
                            const rq = tx.objectStore(sn).getAll();
                            const kq = tx.objectStore(sn).getAllKeys();
                            let vals, keys, left = 2;
                            const done = () => { if (--left === 0) res({ keys, vals }); };
                            rq.onsuccess = () => { vals = rq.result; done(); };
                            kq.onsuccess = () => { keys = kq.result; done(); };
                            rq.onerror = kq.onerror = () => rej(rq.error || kq.error);
                        });
                        for (let i = 0; i < rows.keys.length; i++) {
                            const key = rows.keys[i], v = rows.vals[i];
                            const path = 'idb/' + info.name + '/' + (typeof key === 'string' ? key : sn + '/' + key);
                            if (v instanceof Blob) files[path] = new Uint8Array(await v.arrayBuffer());
                            else if (v instanceof ArrayBuffer) files[path] = new Uint8Array(v);
                            else if (v && v.contents instanceof Blob) files[path] = new Uint8Array(await v.contents.arrayBuffer());
                            else if (typeof v === 'string') files[path] = new TextEncoder().encode(v);
                        }
                    } catch (e) {}
                }
                db.close();
            } catch (e) {}
        }
        return files;
    }

    /* site-popup backup: merge OPFS (butterscotch), localStorage (GXMFS) and
       IndexedDB (godot) saves for <dirKey> into one zip download. */
    async function backupGame(dirKey) {
        const files = await readOpfsFiles(dirKey);
        for (const [k, v] of Object.entries(readGameStorageFiles(dirKey))) if (!(k in files)) files[k] = v;
        for (const [k, v] of Object.entries(await readIdbFiles())) if (!(k in files)) files[k] = v;
        if (!Object.keys(files).length) return false;
        const a = document.createElement('a');
        a.href = URL.createObjectURL(zipStore(files));
        a.download = dirKey + '-saves-backup.zip';
        a.click();
        setTimeout(() => URL.revokeObjectURL(a.href), 10000);
        return true;
    }

    return { dirKeyFromPath, restore, injectIfPending, flushOut, arm, downloadBackup, readOpfsFiles, zipStore, backupGame };
})();
</script>
<script>/* save popup — intercepts clicks on catalog entries flagged save101 (full
   popup incl. the shared saveData*.ini 101% set) or save (backup/play only,
   for non-PT-format games). */
(function () {
    const SAVE_DIRS = new Map(); // dir -> can inject the 101% ini set
    for (const g of [...(typeof MODS !== 'undefined' ? MODS : []), ...(typeof FANGAMES !== 'undefined' ? FANGAMES : [])]) {
        if (g.save101) SAVE_DIRS.set(g.dir, true);
        else if (g.save) SAVE_DIRS.set(g.dir, false);
    }
    if (!SAVE_DIRS.size) return;

    const pop = document.getElementById('popSave');
    const title = document.getElementById('saveTitle');
    const injectBtn = document.getElementById('saveInject');
    let target = null;

    const FILES101 = ['saveData1.ini', 'saveData1C.ini', 'saveData1N.ini',
                      'saveData2.ini', 'saveData2N.ini', 'saveData3.ini', 'saveData3N.ini'];

    // capture phase so we win over main.js's bubble-phase openGame handler
    document.addEventListener('click', (e) => {
        const a = e.target.closest('a[href]');
        if (!a) return;
        const m = (a.getAttribute('href') || '').match(/^(?:games|mods|extras)\/([^/]+)\/?$/);
        if (!m || !SAVE_DIRS.has(m[1])) return;
        e.preventDefault();
        e.stopImmediatePropagation();
        target = { dir: m[1], a };
        const nm = a.querySelector('.cname');
        title.textContent = nm ? nm.textContent : m[1];
        injectBtn.hidden = !SAVE_DIRS.get(m[1]);
        pop.hidden = false;
    }, true);

    const go = () => {
        const a = target && target.a;
        pop.hidden = true;
        if (a && typeof openGame === 'function') {
            openGame(a);
            // cross-origin game frames can't share our sessionStorage — hand
            // the payload to the frame once its document loads.
            const pending = target && sessionStorage.getItem('pu_saveinject_' + target.dir);
            if (pending) {
                const fr = document.querySelector('#gameOverlay iframe');
                if (fr && new URL(fr.src).origin !== location.origin) {
                    const files = JSON.parse(pending);
                    fr.addEventListener('load', () => {
                        try {
                            fr.contentWindow.postMessage(
                                { pu_saveinject: { dir: target.dir, files } },
                                new URL(fr.src).origin,
                            );
                        } catch (_) {}
                    });
                }
            }
        } else if (a) location.href = a.getAttribute('href');
    };

    document.getElementById('saveCancel').addEventListener('click', () => { pop.hidden = true; });
    document.getElementById('saveKeep').addEventListener('click', go);

    document.getElementById('saveBackup').addEventListener('click', async (e) => {
        const btn = e.currentTarget;
        btn.textContent = 'backing up…';
        const ok = await PU_SAVES.backupGame(target.dir);
        btn.textContent = ok ? 'backup saved!' : 'no saves to back up';
        setTimeout(() => { btn.textContent = 'back up my save'; }, 1500);
    });

    injectBtn.addEventListener('click', async (e) => {
        const btn = e.currentTarget;
        btn.textContent = 'loading save…';
        try {
            let out = null;
            if (typeof PU_SAVE101 !== 'undefined') out = PU_SAVE101; // inlined by single-file build
            else {
                out = {};
                for (const f of FILES101) {
                    const r = await fetch('assets/saves101/' + f);
                    if (r.ok) out[f] = await r.text();
                }
            }
            sessionStorage.setItem('pu_saveinject_' + target.dir, JSON.stringify(out));
        } catch {}
        go();
    });
})();
</script>
<script>// swreg.js — registers the root service worker from any page depth.
// sw.js lives at the site root; games load it from games/<name>/ pages.
// First visit the page has no controller, so chunk requests would race the
// install and 404 — wait for activation then reload once; later visits are
// already controlled and load clean.
(function () {
    if (!('serviceWorker' in navigator)) return;
    var root = location.pathname.replace(/\/games\/.*$/, '/').replace(/\/[^/]*$/, '/');
    navigator.serviceWorker.register(root + 'sw.js').then(function () {
        if (!navigator.serviceWorker.controller) {
            navigator.serviceWorker.ready.then(function () { location.reload(); });
        }
    }).catch(function () {});
})();
</script>
</body>
</html>
";
